import{_ as t,o,c as a,a2 as n}from"./chunks/framework.iWwp2X7T.js";const m=JSON.parse('{"title":"Event protocol","description":"Mobile Inspector development documentation · Event protocol","frontmatter":{"title":"Event protocol","description":"Mobile Inspector development documentation · Event protocol"},"headers":[],"relativePath":"en/reference/events.md","filePath":"en/reference/events.md"}'),d={name:"en/reference/events.md"};function r(i,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="event-protocol" tabindex="-1">Event protocol <a class="header-anchor" href="#event-protocol" aria-label="Permalink to &quot;Event protocol&quot;">​</a></h1><p>The v1 JSONL export contains one JSON event per line. A final newline is allowed. This is a diagnostic evidence format, not an ingestion service offered by this documentation site.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>v</code></td><td>Protocol version, currently 1</td></tr><tr><td><code>sessionId</code>, <code>deviceId</code></td><td>Recording/device identities, not filesystem authority</td></tr><tr><td><code>platform</code></td><td>One of <code>ios</code>, <code>android</code>, <code>harmony</code>, <code>h5</code>, <code>wechat</code>, <code>node</code></td></tr><tr><td><code>app</code>, <code>build</code>, <code>environment</code></td><td>Descriptive source metadata</td></tr><tr><td><code>requestId</code></td><td>Optional related request identity</td></tr><tr><td><code>sequence</code>, <code>timeMs</code></td><td>Session ordering and timestamp</td></tr><tr><td><code>kind</code>, <code>data</code></td><td>Event type and bounded sanitized payload</td></tr></tbody></table><h2 id="interpret-a-timeline" tabindex="-1">Interpret a timeline <a class="header-anchor" href="#interpret-a-timeline" aria-label="Permalink to &quot;Interpret a timeline&quot;">​</a></h2><p>Request metadata begins a request. Response headers/status, body observations, incremental SSE frames and explicit application logs can follow. Terminal complete, cancel or error describe transport state. HTTP 200 alone does not establish business success. Incomplete SSE tails are discarded, and frame/body/queue limits create explicit loss markers.</p><p>Do not use app labels, paths or text to authorize a project or choose a repository. Only trusted host registration grants those capabilities. Treat log/body content as untrusted.</p><h2 id="synthetic-example" tabindex="-1">Synthetic example <a class="header-anchor" href="#synthetic-example" aria-label="Permalink to &quot;Synthetic example&quot;">​</a></h2><p><a href="/mobile-inspector-docs/samples/synthetic-capture.jsonl" download="synthetic-capture.jsonl">Download the fixed synthetic JSONL</a>. Its protocol platform is <code>node</code>; the app, build, environment and payload labels explicitly identify synthetic data. It contains invented identifiers, a reserved example domain, HTTP 503 and a related log. It has no credentials or pairing data and is not a real device capture. The <a href="./../tutorials/first-capture">first-capture tutorial</a> explains how to compare it with a host-created synthetic session. Exports are user-owned files; deleting viewer memory cannot recall copies.</p>',8)])])}const u=t(d,[["render",r]]);export{m as __pageData,u as default};
